#include "audio_sequencer.h"

/* AUDIO_SEQUENCER_BASIC_INSTRUMENT_COUNT -- the boundary audio_resolve_
 * instrument maps against: PICO-8 instruments 0-7 are the 8 baked basic
 * waveforms (chunk 2's own AUDIO_INSTRUMENT_COUNT, psx-slipways/
 * audio_waveforms.h), 8-15 are the undecoded custom-instrument slots that
 * fall back to (n - this constant). Deliberately NOT #include
 * "audio_waveforms.h" to pick this up as AUDIO_INSTRUMENT_COUNT directly:
 * that header is a chunk-2 GENERATED file (tools/gen_psx_waveforms.py,
 * gitignored, regenerated by `make audio-waveforms`) with no other reason
 * for this chunk to depend on it -- pulling it in here would make this
 * chunk's own Makefile target need that generation step as a prerequisite
 * too, an unnecessary coupling for a chunk whose own scope is pure
 * arithmetic against a fixed, well-documented constant (docs/prd/triage/
 * psx-spu-audio.md's own Implementation Chunks item 3: "audio_resolve_
 * instrument(0..15) -> 0..7"). The two constants are independently
 * cross-checked to agree, not by inclusion but by citation: 8 basic PICO-8
 * instruments is itself real, public, stable PICO-8 engine knowledge (see
 * audio_sequencer.h's own doc comment on audio_resolve_instrument), not a
 * value that could drift out of sync with chunk 2's own AUDIO_INSTRUMENT_*
 * constants without both this codebase's own host tests (audio_sequencer_
 * test.c, gen_psx_waveforms_test.c) and this PRD's own instrument-palette
 * citation all needing to change together. */
#define AUDIO_SEQUENCER_BASIC_INSTRUMENT_COUNT 8

int audio_resolve_instrument(int pico8_instrument) {
    if (pico8_instrument < AUDIO_SEQUENCER_BASIC_INSTRUMENT_COUNT) {
        return pico8_instrument;
    }
    return pico8_instrument - AUDIO_SEQUENCER_BASIC_INSTRUMENT_COUNT;
}

/* Stateful-wrapper-free -- unlike rules_tech.c's own rules_tech_init/
 * rules_tech_update pair (which owns its OWN module-level globals, since
 * rules_tech.h's own state is a single global menu toggle), this module
 * owns NO globals of its own: a real caller (a later, PSX-only chunk) owns
 * 4 separate audio_channel_state_t instances (one per PICO-8 logical
 * channel, docs/prd/triage/psx-spu-audio.md's own "4 real SPU voices, one
 * per PICO-8 logical channel" design) and threads each one through these
 * functions explicitly -- matching effects.c's own in/out-parameter
 * convention (effects_kick_step, effects_popup_step) rather than
 * rules_tech.c's own single-owned-global convention, since there is
 * genuinely more than one instance of this state in the real system. */

void audio_channel_init(audio_channel_state_t *ch) {
    ch->is_music = 1;
    ch->music_note_index = 0;
    ch->music_tick = 0;
    ch->sfx_pending_stop = 0;
}

void audio_channel_sfx_trigger(audio_channel_state_t *ch) {
    ch->is_music = 0;
    ch->sfx_pending_stop = 0;
    /* music_note_index/music_tick are deliberately NOT touched here -- see
     * audio_sequencer.h's own doc comment on audio_channel_sfx_trigger for
     * why this omission is the entire point of this function. */
}

void audio_channel_sfx_finished(audio_channel_state_t *ch) {
    /* Defensive guard (audio_sequencer.h's own doc comment on this
     * function): only signal a real pending stop if this channel was
     * actually preempted (is_music was 0) before this call -- a stray
     * duplicate key-off report on an already-music-driven channel has no
     * real sfx voice to stop. */
    if (!ch->is_music) {
        ch->sfx_pending_stop = 1;
    }
    ch->is_music = 1;
    /* music_note_index/music_tick are deliberately NOT touched here either
     * -- the same "emergent resume" guarantee as above, from the opposite
     * direction. */
}
